node -e "
const fs = require('fs');
const r = JSON.parse(fs.readFileSync('rule.json', 'utf8'));

// Let's create an environment to execute detail_find_rule or extract what it pushes to d:
// In detail_find_rule:
// We can mock the environment and run detail_find_rule to see what item.url is produced!
const vm = require('vm');
const context = {
    MY_URL: 'http://127.0.0.1:18002/detail?[REDACTED_QUERY]',
    MY_PARAMS: { bridgeBase: 'http://127.0.0.1:18002' },
    request: function(u) {
        return JSON.stringify({
            ok: true,
            data: {
                id: 123,
                name: '测试动漫',
                parts: [{ play: 'default', play_zh: '默认', part: ['第1集'] }]
            }
        });
    },
    setResult: function(res) {
        context.__result = res;
    }
};

vm.createContext(context);
const code = r.detail_find_rule.replace(/^js:\s*/, '');
vm.runInContext(code, context);

const item = context.__result[context.__result.length - 1];
console.log('Generated item title:', item.title);
console.log('Generated item url:', item.url);
const lazyPart = item.url.split('@lazyRule=')[1];
console.log('\n--- lazyPart ---\n', lazyPart);
const lazyCode = lazyPart.replace(/^\.js:\s*/, '');
try {
    new Function(lazyCode);
    console.log('Compiled OK!');
} catch (e) {
    console.log('Compile Error:', e.name, e.message);
}
"
